<div class="page-actions"><div><p class="mb-0">Create customer login for self-service portal.</p></div><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#portalUserModal">New Portal User</button></div><div class="card-panel"><table class="table datatable"><thead><tr><th>Customer</th><th>Name</th><th>Email</th><th>Status</th><th>Last Login</th></tr></thead><tbody><?php foreach($portalUsers as $u): ?><tr><td><?= e($u['customer_name']) ?></td><td><?= e($u['name']) ?></td><td><?= e($u['email']) ?></td><td><span class="status-badge"><?= e($u['status']) ?></span></td><td><?= e($u['last_login_at']??'-') ?></td></tr><?php endforeach; ?></tbody></table></div><div class="modal fade" id="portalUserModal"><div class="modal-dialog"><form class="modal-content ajax-form" method="post" action="<?= url('/portal-users') ?>"><?= csrf_field() ?><div class="modal-header"><h5>Customer Portal User</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><select class="form-select mb-2" name="customer_id" required><option value="">Customer</option><?php foreach($customers as $c): ?><option value="<?= $c['id'] ?>"><?= e($c['name']) ?></option><?php endforeach; ?></select><input class="form-control mb-2" name="name" placeholder="Contact name" required><input class="form-control mb-2" type="email" name="email" placeholder="Email" required><input class="form-control" type="password" name="password" minlength="8" placeholder="Temporary password" required></div><div class="modal-footer"><button class="btn btn-primary">Create Access</button></div></form></div></div>
